package cl.skinspad.reporte.soporte;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import org.springframework.http.*;import com.fasterxml.jackson.databind.*;
import java.util.*;import java.util.concurrent.*;import java.math.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static cl.skinspad.reporte.soporte.EstadosSoporte.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:soporte;MODE=MySQL;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000","spring.datasource.driver-class-name=org.h2.Driver","spring.jpa.hibernate.ddl-auto=create-drop","escrow.job-initial-ms=3600000","soporte.job-inicial-ms=3600000"}) @AutoConfigureMockMvc
class SoporteIntegrationTest {
@Autowired MockMvc mvc;@Autowired ObjectMapper mapper;@Autowired ReporteRepository reportes;@Autowired SoporteEventoRepository eventos;@Autowired SoporteNotificacionRepository avisos;@Autowired SoporteAdjuntoRepository adjuntos;@Autowired SoporteCuotaRepository cuotas;@Autowired SoporteObjetivoRepository objetivos;@Autowired AlertaPrecioRepository precios;@Autowired ReporteAcciones acciones;@Autowired PrecioService precioService;
 @MockitoBean cl.skinspad.reporte.stats.StatsUserClient sessions;@MockitoBean SoporteCatalogoClient catalogo;@MockitoBean SoporteUsuarioClient usuarios;
 @MockitoBean PagoClient pagos;
 @MockitoBean TicketConsultas consulta;
 @BeforeEach void preparar(){adjuntos.deleteAll();reportes.deleteAll();eventos.deleteAll();avisos.deleteAll();cuotas.deleteAll();objetivos.deleteAll();precios.deleteAll();
  when(sessions.validate(anyString())).thenAnswer(x->new cl.skinspad.reporte.stats.StatsUserClient.Identity(x.getArgument(0),((String)x.getArgument(0)).startsWith("admin")?"admin":"cliente",false));
  when(usuarios.obtener(anyString())).thenAnswer(x->new SoporteUsuarioClient.Usuario(x.getArgument(0),((String)x.getArgument(0)).startsWith("admin")?"admin":"cliente",false));
  when(catalogo.obtener(anyLong())).thenAnswer(x->skin(x.getArgument(0),100));when(catalogo.listar()).thenReturn(List.of());
 }
 SoporteCatalogoClient.Publicacion skin(long id,int precio){return new SoporteCatalogoClient.Publicacion(id,"AK-47 | Redline","seller","rifle","ft",false,new BigDecimal("0.2"),"clasificado",BigDecimal.valueOf(precio),"ACTIVO",false);}
 JsonNode enviar(String ruta,String usuario,Object body,int status)throws Exception{var result=mvc.perform(post(ruta).header("Authorization","Bearer "+usuario).contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsBytes(body))).andExpect(status().is(status)).andReturn();return result.getResponse().getContentAsString().isBlank()?mapper.createObjectNode():mapper.readTree(result.getResponse().getContentAsString());}
 Map<String,Object> reporte(String tipo,String id){return Map.of("tipoObjetivo",tipo,"objetivoId",id,"motivo","OTRO","descripcion","Descripción del problema");}
 long reporte()throws Exception{return enviar("/api/reportes","buyer",reporte("PUBLICACION","1"),201).get("id").asLong();}
 Map<String,Object> resolver(long id,String accion,String estado){return Map.of("version",reportes.findById(id).orElseThrow().getVersion(),"estado",estado,"accion",accion,"motivo","Comprobado por soporte","resumenPublico","Revisamos tu solicitud","confirmado",true);}
 @Test void duplicadosYAutoreporte()throws Exception{reporte();enviar("/api/reportes","buyer",reporte("PUBLICACION","01"),409);enviar("/api/reportes","seller",reporte("PUBLICACION","1"),400);enviar("/api/reportes","buyer",reporte("USUARIO","buyer"),400);assertEquals(1,reportes.count());}
 @Test void tresUsuariosMarcanUrgenteSinDespublicar()throws Exception{for(String u:List.of("buyer","buyer2","buyer3"))enviar("/api/reportes",u,reporte("PUBLICACION","1"),201);assertTrue(reportes.findAll().stream().allMatch(r->r.getPrioridad()==Prioridad.URGENTE));verify(catalogo,never()).despublicar(anyLong(),any());}
 @Test void sinAccionRechazoYAdvertenciaCierranSinSancionAutomatica()throws Exception{long id=reporte();enviar("/api/admin/reportes/"+id+"/resolver","admin",resolver(id,"SIN_ACCION","RECHAZADO"),200);assertNull(reportes.findById(id).orElseThrow().getClaveAbierta());enviar("/api/reportes","buyer",reporte("PUBLICACION","1"),201);long segundo=reportes.findAll().stream().mapToLong(Reporte::getId).max().orElseThrow();enviar("/api/admin/reportes/"+segundo+"/resolver","admin",resolver(segundo,"ADVERTENCIA","RESUELTO"),200);assertEquals(1,avisos.findTop50ByDestinatarioOrderByIdDesc("seller").size());assertFalse(avisos.findTop50ByDestinatarioOrderByIdDesc("seller").get(0).getTexto().contains("buyer"));verify(usuarios,never()).suspender(anyString(),any());}
 @Test void despublicarYSuspenderReutilizanAdaptadores()throws Exception{long id=reporte();enviar("/api/admin/reportes/"+id+"/resolver","admin",resolver(id,"PUBLICACION_DESPUBLICADA","RESUELTO"),200);acciones.ejecutar(id);verify(catalogo,times(1)).despublicar(eq(1L),argThat(o->o.referencia().startsWith("REP-"+id+"-")&&o.actor().equals("admin")));long otro=enviar("/api/reportes","buyer",reporte("USUARIO","seller"),201).get("id").asLong();enviar("/api/admin/reportes/"+otro+"/resolver","admin",resolver(otro,"USUARIO_SUSPENDIDO","RESUELTO"),200);verify(usuarios).suspender(eq("seller"),any());}
 @Test void dosAdministradoresSoloUnoResuelve()throws Exception{long id=reporte();var body=mapper.writeValueAsBytes(resolver(id,"SIN_ACCION","RESUELTO"));var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);try{var results=new ArrayList<Future<Integer>>();for(String a:List.of("admin","admin2"))results.add(pool.submit(()->{gate.await();return mvc.perform(post("/api/admin/reportes/"+id+"/resolver").header("Authorization","Bearer "+a).contentType(MediaType.APPLICATION_JSON).content(body)).andReturn().getResponse().getStatus();}));gate.countDown();var codes=new ArrayList<Integer>();for(var f:results)codes.add(f.get(15,TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(200,409),codes);assertEquals(1,eventos.findByEntidadAndEntidadIdOrderById("REPORTE",id).stream().filter(e->e.getAccion().equals("ACCION_CONFIRMADA")).count());}finally{pool.shutdownNow();}}
 @Test void precioValidadoNoRealertaHastaQueCambiePublicacion()throws Exception{var lista=new ArrayList<SoporteCatalogoClient.Publicacion>();lista.add(skin(1,1000));for(long i=2;i<=7;i++)lista.add(skin(i,100));when(catalogo.listar()).thenReturn(lista);when(catalogo.obtener(1L)).thenReturn(lista.get(0));precioService.analizar();var a=precios.findById(1L).orElseThrow();precioService.validar(1L,new SoporteDtos.ValidarPrecio(a.getVersion(),"Pieza revisada",true),"admin");precioService.analizar();assertEquals("VALIDADA",precios.findById(1L).orElseThrow().getEstado());lista.set(0,skin(1,1100));precioService.analizar();assertEquals("PENDIENTE",precios.findById(1L).orElseThrow().getEstado());}
 @Test void respuestaRemotaPerdidaReintentaMismaReferenciaSinCerrarAntes()throws Exception{
  long id=reporte();doThrow(new RuntimeException("Respuesta perdida")).doNothing().when(catalogo).despublicar(eq(1L),any());
  enviar("/api/admin/reportes/"+id+"/resolver","admin",resolver(id,"PUBLICACION_DESPUBLICADA","RESUELTO"),200);
  var pendiente=reportes.findById(id).orElseThrow();assertTrue(pendiente.isAccionPendiente());assertEquals(Estado.ABIERTO,pendiente.getEstado());assertTrue(avisos.findTop50ByDestinatarioOrderByIdDesc("buyer").isEmpty());
  acciones.ejecutar(id);acciones.ejecutar(id);var orden=org.mockito.ArgumentCaptor.forClass(SoporteCatalogoClient.Orden.class);verify(catalogo,times(2)).despublicar(eq(1L),orden.capture());assertEquals(orden.getAllValues().get(0),orden.getAllValues().get(1));assertFalse(orden.getValue().motivo().contains("Comprobado por soporte"));assertEquals(Estado.RESUELTO,reportes.findById(id).orElseThrow().getEstado());assertEquals(1,avisos.findTop50ByDestinatarioOrderByIdDesc("buyer").size());
 }
 @Test void rechazoRemotoDefinitivoPermiteElegirOtraAccion()throws Exception{
  long id=reporte();var request=feign.Request.create(feign.Request.HttpMethod.POST,"http://catalogo",Map.of(),null,java.nio.charset.StandardCharsets.UTF_8,null);var response=feign.Response.builder().status(409).reason("Reserva activa").request(request).headers(Map.of()).build();doThrow(feign.FeignException.errorStatus("despublicar",response)).when(catalogo).despublicar(anyLong(),any());
  enviar("/api/admin/reportes/"+id+"/resolver","admin",resolver(id,"PUBLICACION_DESPUBLICADA","RESUELTO"),200);var r=reportes.findById(id).orElseThrow();assertFalse(r.isAccionPendiente());assertEquals(Estado.ABIERTO,r.getEstado());assertNull(r.getResolucion());enviar("/api/admin/reportes/"+id+"/resolver","admin",resolver(id,"SIN_ACCION","RESUELTO"),200);assertEquals(Estado.RESUELTO,reportes.findById(id).orElseThrow().getEstado());
 }
 @Test void reportanteNoVeMotivoInternoNiPrioridad()throws Exception{
  long id=reporte();enviar("/api/admin/reportes/"+id+"/resolver","admin",resolver(id,"SIN_ACCION","RESUELTO"),200);var result=mvc.perform(get("/api/reportes/"+id).header("Authorization","Bearer buyer")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertFalse(result.contains("Comprobado por soporte"));assertFalse(result.contains("SOLICITAR_ACCION"));assertTrue(result.contains("Revisamos tu solicitud"));
 }
}
